 FOR p IN SELECT value FROM jsonb_array_elements('[{"old":"supabase.rpc(''admin_marketing_dashboard'',","new":"supabase.rpc(''admin_traffic_dashboard_v266'',","count":2},{"old":"<h2>Kampane</h2>","new":"<h2>Návštevnosť</h2>","count":1},{"old":"<span>Kampane</span>","new":"<span>Návštevnosť</span>","count":1},{"old":"aria-label=\"Kampane\"","new":"aria-label=\"Návštevnosť\"","count":1},{"old":"p_from:cmShiftV71(day,-1),p_to:day","new":"p_from:cmShiftV71(day,-7),p_to:day","count":1},{"old":"</body>","new":"<style id=\"chvo-traffic-v266-style\">\n/* Scoped analytics, independent of dog/admin workflow styling. */\n#campaignsSection #campaignMetaStampV76,#campaignsSection #campaignFunnelAdviceV88{display:none!important}\n#campaignsSection .campaign-status-v71:empty{display:none}\n#campaignsSection .campaign-header-v71 h2{font-size:26px;letter-spacing:-.7px}\n#campaignsSection .cm98-tabs{display:grid;grid-template-columns:1fr 1fr;gap:6px;background:#eeeef3;padding:5px;border:0;border-radius:17px;margin:0 0 18px}\n#campaignsSection .cm98-tabs button{border:0!important;border-radius:12px;min-height:44px;background:transparent;color:#667085;font-size:15px;font-weight:800}\n#campaignsSection .cm98-tabs button.is-active{background:white;color:#c65310;box-shadow:0 2px 7px #1018280c}\n.t266{--ink:#202a3c;--muted:#798294;--line:#e9edf2;--orange:#f47927;color:var(--ink);min-width:0;font-variant-numeric:tabular-nums}\n.t266 *{box-sizing:border-box}.t266 h3,.t266 h4,.t266 p,.t266 figure{margin:0}.t266 h3{font-size:17px;letter-spacing:-.3px}.t266 h4{font-size:14px}.t266 button{font:inherit;cursor:pointer}.t266 button:focus-visible,.t266 [tabindex]:focus-visible{outline:3px solid #f9ab70;outline-offset:3px}\n.t266-panel{background:white;border:1px solid var(--line);border-radius:21px;padding:20px;margin:0 0 16px;box-shadow:0 4px 18px #10182804;min-width:0}\n.t266-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:18px!important}.t266-title small,.t266-muted{color:var(--muted);font-size:12px;line-height:1.5}\n.t266-kpis{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:16px}\n.t266-kpi{border:1px solid var(--line);border-radius:19px;padding:19px;min-width:0;background:white}.t266-kpi:first-child{background:#fff6ed;border-color:#ffe2c6}.t266-kpi>span{display:block;font-size:12px;font-weight:650;color:#767d8d;margin-bottom:12px}.t266-kpi>strong{font-size:32px;font-weight:850;line-height:1.1;letter-spacing:-1px;display:block;overflow-wrap:anywhere}.t266-kpi>small{display:block;margin-top:9px;font-size:11px;color:#7b8493}\n.t266-pages{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 17px}.t266-pages button,.t266-metric button{border:1px solid #e7eaf0;background:white;border-radius:12px;min-height:40px;padding:9px 13px;font-size:12px;font-weight:750;color:#727b8a}.t266-pages button[aria-pressed=true],.t266-metric button[aria-pressed=true]{background:#26364c;color:white;border-color:#26364c}\n.t266-line svg{width:100%;height:auto;display:block;overflow:visible}.t266-line text{font-family:inherit;font-size:11px;fill:#798294}.t266-line figcaption{min-height:22px;font-size:12px;color:#7b8493;text-align:center;margin-top:4px}.t266-line [data-t266-point]{cursor:pointer}.t266-line [data-t266-point]:hover circle{r:6}\n.t266-pagebars{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;align-items:end}.t266-pagecol{text-align:center;min-width:0}.t266-column{height:130px;background:#f7f8fa;border-radius:11px;display:flex;align-items:end;justify-content:center;margin:10px 0}.t266-column i{display:block;width:100%;border-radius:10px;min-height:0}.t266-pagecol>strong{font-size:19px}.t266-pagecol>span{display:block;font-size:11px;line-height:1.5;font-weight:700;color:#7b8493;overflow-wrap:anywhere}\n.t266-donut-layout{display:grid;grid-template-columns:145px minmax(0,1fr);gap:22px;align-items:center}.t266-donut{width:145px;height:145px;border-radius:50%;display:grid;place-items:cen