gap:9px;font-size:12px;margin-bottom:7px}.t266-fieldhead span{min-width:0;overflow-wrap:anywhere}.t266-fieldhead b{white-space:nowrap;font-size:10px;color:#798294;font-weight:550}.t266-fieldtrack{height:8px;background:#edf4ee;display:flex;border-radius:6px;overflow:hidden}.t266-fieldtrack i{height:100%;display:block}.t266-fieldlegend{display:flex;gap:13px;flex-wrap:wrap;margin-bottom:18px;font-size:10px;color:#798294}.t266-fieldlegend span{display:flex;align-items:center;gap:5px}\n.t266-campaign{display:block;width:100%;text-align:left;border:1px solid var(--line);background:white;border-radius:18px;padding:19px;margin-bottom:11px;color:var(--ink)}.t266-campaign>strong{display:block;font-size:15px;line-height:1.5;overflow-wrap:anywhere}.t266-campaignhead{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:12px}.t266-status{font-size:10px;background:#eff8f1;color:#4d8461;padding:5px 8px;border-radius:8px}.t266-status.paused{background:#f3f4f6;color:#89909b}.t266-mini{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:15px}.t266-mini span{font-size:10px;color:#798294}.t266-mini b{display:block;font-size:16px;color:#273246;margin-top:5px;overflow-wrap:anywhere}\n.t266-back{border:0;border-radius:11px;min-height:40px;padding:8px 12px;background:#f2f4f7;font-size:13px;font-weight:700;color:#536071;margin-bottom:14px}\n.t266-metric{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:18px}.t266-ads{border-top:1px solid var(--line);padding:0}.t266-ads details{padding:16px 0;border-bottom:1px solid var(--line)}.t266-ads summary{display:flex;align-items:center;gap:12px;cursor:pointer;list-style:none;font-size:13px;font-weight:800;min-height:52px}.t266-ads summary::-webkit-details-marker{display:none}.t266-ads summary::after{content:''⌄'';margin-left:auto;color:#8d96a5}.t266-ads details[open] summary::after{content:''⌃''}.t266-ads summary img,.t266-thumb{width:54px;height:54px;object-fit:cover;flex:none;border-radius:12px;background:#f7f1ed;display:grid;place-items:center}.t266-ads summary span{min-width:0;overflow-wrap:anywhere}.t266-ads summary small{display:block;font-size:11px;font-weight:500;color:#798294;margin-top:5px}.t266-ads details .t266-kpis{margin-top:18px}.t266-ads details .t266-kpi{padding:13px;border-radius:13px}.t266-ads details .t266-kpi>strong{font-size:24px}.t266-ads .t266-mini{row-gap:17px;margin-bottom:8px}.t266-empty{padding:20px 0;color:#9098a5;font-size:13px;line-height:1.6}.t266-report-summary{font-size:14px;line-height:1.7;color:#657083;margin:0 0 18px!important}.t266-report .t266-panel{box-shadow:none}.t266-report .t266-kpi>strong{font-size:27px}\n@media(min-width:750px){.t266-twocol{display:grid;grid-template-columns:1fr 1fr;gap:16px}.t266-twocol>.t266-panel{margin-bottom:16px}.t266-fields{grid-template-columns:1fr 1fr;column-gap:26px}.t266-kpis.meta{grid-template-columns:repeat(4,minmax(0,1fr))}}\n@media(max-width:420px){.t266-panel{padding:16px;border-radius:18px}.t266-kpi{padding:16px}.t266-kpi>strong{font-size:29px}.t266-donut-layout{grid-template-columns:120px minmax(0,1fr);gap:13px}.t266-donut{width:120px;height:120px}.t266-donut>div{width:90px;height:90px}.t266-pages{gap:5px}.t266-pages button{padding:8px 10px;font-size:11px}.t266-funnel{gap:6px}.t266-step{padding:12px 9px}.t266-title{align-items:start}.t266-pagebars{gap:10px}}\n.cm-report-body-v76 .t266-report .t266-panel{padding:20px;border:1px solid #e9edf2}.cm-report-body-v76 .t266-report .t266-report-summary{font-size:14px;line-height:1.7;color:#657083}\n@media(max-width:420px){.cm-report-body-v76 .t266-report .t266-panel{padding:16px}}\n\n</style><script id=\"chvo-traffic-v266\">\n/* Read-only presentation for traffic and Meta analytics. */\n(function trafficV266(){\n''use strict'';\nconst $=id=>document.getElementById(id),s=cmSafeV71,n=v=>v==null?''—'':cmIntV71(v),eur=v=>v==null?''—'':cmEurV71(v);\nconst pages={WEB:{name:''Hlavný web'',color:''#ec985b''},LEAD:{name:''Lead'',color:''#ab90d6''},STENIATKA:{name:''Šteniatka'',color:''#7ebca8''},EN:{name:''English'',color:''#7ba7d0''}};\nconst buttons={explore_daycare:''Zistiť viac'',inquiry_cta:''Chcem sa informovať'',phone_click:''Zavolať'',success_pricing_click:''Pozrieť cenník''};\nconst fields={...cmFunnelFieldsV89,email:''E-mail'',suhlas:''Súhlas''};\nconst sourceGroups={meta_paid:''Reklama'',google_paid:''Reklama'',google_organic:''Google'',bing_organic:''Vyhľadávače'',instagram_organic:''Sociálne siete'',facebook_organic:''Sociálne siete'',meta_referral:''Sociálne siete'',threads_organic:''Sociálne siete'',tiktok_organic:''Sociálne siete'',youtube_organic:''Sociálne siete'',direct:''Priame / neznáme'',internal_navigation:''Prechody na webe'',referral:''Odkazy'',utm_other:''Označené odkazy''};\nconst palette=[''#ee9d60'',''#a992ce'',''#8ab7a5'',''#8eaccb'',''#c6b28a'',''#d2a4ac'',''#a8b6bb'',''#d0c6b4''];\nlet metric=''amount_spent'';\nconst sum=(rows,key)=>rows.reduce((a,r)=>a+(Number(r[key])||0),0);\nconst rows=(p,key,from,to,page=''ALL'')=>(p?.[key]||[]).filter(r=>r.report_date>=from&&r.report_date<=to&&(page===''ALL''||r.page_group===page));\nconst panel=(title,body,aside='''')=>''<section class=\"t266-panel\"><div class=\"t266-title\"><h3>''+s(title)+''</h3>''+(aside?''<small>''+s(aside)+''</small>'':'''')+''</div>''+body+''</section>'';\nconst empty=msg=>''<p class=\"t266-empty\">''+s(msg)+''</p>'';\nconst kpi=(label,value,sub='''')=>''<article class=\"t266-kpi\"><span>''+s(label)+''</span><strong>''+s(value)+''</strong>''+(sub?''<small>''+s(sub)+''</small>'':'''')+''</article>'';\nconst paid=r=>[''meta_paid'',''google_paid''].includes(r.source_channel);\nfunction days(from,to){const out=[];for(let d=from;d<=to&&out.length<181;d=cmShiftV71(d,1))out.push(d);return out}\nfunction line(title,from,to,getValue,color=''#ee9d60'',unit=''''){const dates=days(from,to),values=dates.map(getValue),valid=values.filter(v=>v!==null&&Number.isFinite(v));\n if(!valid.length)return panel(title,empty(''Za toto obdobie zatiaľ nemáme údaje.''));\n const max=Math.max(1,...valid),upper=unit===''€''?Math.ceil(max*1.15*10)/10:Math.max(1,Math.ceil(max*1.15)),x=i=>48+(dates.length===1?310:i/(dates.length-1)*620),y=v=>202-v/upper*164;\n const points=values.map((v,i)=>v===null?null:{i,v}).filter(Boolean);let path='''',last=-2;\n for(const q of points){path+=(q.i===last+1?''L'':''M'')+x(q.i).toFixed(1)+'',''+y(q.v).toFixed(1)+'' '';last=q.i}\n const labels=[...new Set([0,Math.round((dates.length-1)/4),Math.round((dates.length-1)/2),Math.round((dates.length-1)*3/4),dates.length-1])];\n const svg=''<figure class=\"t266-line\"><svg viewBox=\"0 0 720 254\" role=\"img\" aria-label=\"''+s(title)+''\"><title>''+s(title)+''</title>''+[0,.5,1].map(f=>{const yy=202-f*164;return ''<line x1=\"48\" y1=\"''+yy+''\" x2=\"668\" y2=\"''+yy+''\" stroke=\"#edf0f4\"/><text x=\"38\" y=\"''+(yy+4)+''\" text-anchor=\"end\">''+s(unit===''€''?cmDecV71(f*upper):Math.round(f*upper))+''</text>''}).join('''')+''<text x=\"48\" y=\"18\">''+s(unit||''Počet návštev'')+''</text><path d=\"''+path+''\" fill=\"none\" stroke=\"''+color+''\" stroke-width=\"3\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/>''+points.map(q=>''<g tabindex=\"0\" role=\"button\" data-t266-point=\"''+s(cmDayV71(dates[q.i])+'' · ''+(unit===''€''?eur(q.v):n(q.v))+(unit&&unit!==''€''?'' ''+unit:''''))+''\" aria-label=\"''+s(dates[q.i]+'': ''+q.v)+''\"><circle cx=\"''+x(q.i)+''\" cy=\"''+y(q.v)+''\" r=\"4\" fill=\"white\" stroke=\"''+color+''\" stroke-width=\"2\"/><circle cx=\"''+x(q.i)+''\" cy=\"''+y(q.v)+''\" r=\"12\" fill=\"transparent\"/><title>''+s(cmDayV71(dates[q.i])+'': ''+n(q.v))+''</title></g>'').join('''')+labels.map(i=>''<text x=\"''+x(i)+''\" y=\"228\" text-anchor=\"middle\">''+s(cmDayV71(dates[i]))+''</text>'').join('''')+''<text x=\"668\" y=\"249\" text-anchor=\"end\">Dátum</text></svg><figcaption aria-live=\"polite\"></figcaption></figure>'';\n return panel(title,svg);\n}\nfunction pageBars(traffic){const values=Object.keys(pages).map(key=>({key,value:sum(traffic.filter(r=>r.page_group===key),''landings'')})),max=Math.max(1,...values.map(x=>x.value));return panel(''📊 Návštevy podľa stránky'',''<div class=\"t266-pagebars\">''+values.map(v=>''<div class=\"t266-pagecol\"><strong>''+n(v.value)+''</strong><div class=\"t266-column\"><i style=\"height:''+(v.value/max*100)+''%;background:''+pages[v.key].color+''\"></i></div><span>''+s(pages[v.key].name)+''</span></div>'').join('''')+''</div>'')}\nfunction donut(traffic){const map=new Map();for(const r of traffic){const k=sourceGroups[r.source_channel]||''Ostatné'';map.set(k,(map.get(k)||0)+(Number(r.landings)||0))}const list=[...map].sort((a,b)=>b[1]-a[1]),total=sum(traffic,''landings'');let start=0;const segments=list.map(([name,val],i)=>{const end=start+val/Math.max(1,total)*100,out=palette[i%palette.length]+'' ''+start+''% ''+end+''%'';start=end;return out});return panel(''🧭 Odkiaľ prichádzajú'',total?''<div class=\"t266-donut-layout\"><div class=\"t266-donut\" style=\"background:conic-gradient(''+segments.join('','')+'')\" role=\"img\" aria-label=\"Zdroje návštevnosti\"><div><strong>''+n(total)+''</strong><small>návštev stránok</small></div></div><div class=\"t266-legend\">''+list.map(([name,val],i)=>''<div class=\"t266-source\"><i class=\"t266-dot\" style=\"background:''+palette[i%palette.length]+''\"></i><span>''+s(name)+''</span><b>''+n(val)+''<small>''+cmDecV71(val/total*100)+'' %</small></b></div>'').join('''')+''</div></div>'':empty(''Zatiaľ bez návštev.''))}\nfunction clicks(activity){const map=new Map();for(const r of activity){if(!buttons[r.event_name])continue;const k=r.page_group+''|''+r.event_name+''|''+r.event_source;if(!map.has(k))map.set(k,{...r,events:0});map.get(k).events+=Number(r.events)||0}const list=[...map.values()].sort((a,b)=>b.events-a.events),max=Math.max(1,...list.map(r=>r.events));return panel(''👆 Kliknutia na tlačidlá'',list.length?list.map(r=>''<div class=\"t266-click\"><div><span class=\"t266-cta\">''+s(butt